END;
$$;

-- -----------------------------------------------------------------
-- PHASE 11 — project_type lookup table
-- -----------------------------------------------------------------

CREATE TABLE IF NOT EXISTS "public"."project_type" (
    "id"          bigint                      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name"        text                        NOT NULL UNIQUE,
    "description" text,
    "created_at"  timestamp with time zone    NOT NULL DEFAULT now(),
    "updated_at"  timestamp without time zone          DEFAULT now()
);

ALTER TABLE "public"."project_type" OWNER TO "postgres";
COMMENT ON TABLE "public"."project_type" IS 'Lookup table for the type of roofing project (Residential, Commercial, etc.).';

INSERT INTO "public"."project_type" ("id", "name", "description") VALUES
  (1, 'Residential',      'Single-family or multi-family residential property.'),
  (2, 'Commercial',       'Commercial or industrial building.'),
  (3, 'New Construction', 'New build — no existing roof to tear off.'),
  (4, 'Insurance Claim',  'Job driven by an insurance claim (hail, wind, storm damage).'),
  (5, 'Maintenance',      'Routine maintenance or minor repair.')
ON CONFLICT (id) DO NOTHING;

ALTER TABLE "public"."project_type" ALTER COLUMN "id" RESTART WITH 6;

-- project_type_id FK on projects
ALTER TABLE "public"."projects"
  ADD COLUMN IF NOT EXISTS "project_type_id" bigint
  REFERENCES "public"."project_type"("id") ON DELETE SET NULL;

COMMENT ON COLUMN "public"."projects"."project_type_id"
  IS 'FK to project_type. Classifies the project (Residential, Commercial, Insurance Claim, etc.).';

-- project_type — read-only for authenticated users
ALTER TABLE "public"."project_type" ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE  schemaname = 'public'
      AND  tablename  = 'project_type'
      AND  policyname = 'Enable read for authenticated users'
