-- -----------------------------------------------------------------
-- PHASE 12 — Structured address + property owner + status default
--
-- Design principle: projects are identified by address first.
-- street_address is the canonical primary field. The legacy `address`
-- text column is kept for backward compatibility and should be kept
-- in sync by application code.
-- -----------------------------------------------------------------

ALTER TABLE "public"."projects"
  ADD COLUMN IF NOT EXISTS "street_address"      text,
  ADD COLUMN IF NOT EXISTS "city"                text,
  ADD COLUMN IF NOT EXISTS "state"               text,
  ADD COLUMN IF NOT EXISTS "zipcode"             text,
  ADD COLUMN IF NOT EXISTS "property_owner_name" text;

COMMENT ON COLUMN "public"."projects"."street_address"
  IS 'Primary project identifier. Required for all new projects. Populated via Google Maps Places autocomplete.';
COMMENT ON COLUMN "public"."projects"."city"
  IS 'City of the job site.';
COMMENT ON COLUMN "public"."projects"."state"
  IS 'State of the job site (2-letter code, e.g. TX).';
COMMENT ON COLUMN "public"."projects"."zipcode"
  IS 'Zip/postal code of the job site.';
COMMENT ON COLUMN "public"."projects"."property_owner_name"
  IS 'Free-text property owner name. Used before a full Customer record is created.';

-- Back-fill structured address from the legacy unstructured column
UPDATE "public"."projects"
SET    "street_address" = "address"
WHERE  "street_address" IS NULL AND "address" IS NOT NULL;

-- Set a default on the legacy status column to prevent INSERT failures
ALTER TABLE "public"."projects"
  ALTER COLUMN "status" SET DEFAULT 'Lead';

-- -----------------------------------------------------------------
-- PHASE 13 — Insurance claim & permit fields
-- -----------------------------------------------------------------

-- Insurance claim tracking (common in hail / storm damage roofing)
ALTER TABLE "public"."projects"
  ADD COLUMN IF NOT EXISTS "is_insurance_claim" boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS "claim_number"       text,
  ADD COLUMN IF NOT EXISTS "insurance_company"  text,
  ADD COLUMN IF NOT EXISTS "adjuster_name"      text,
  ADD COLUMN IF NOT EXISTS "adjuster_phone"     text,
  ADD COLUMN IF NOT EXISTS "date_of_loss"       date;

COMMENT ON COLUMN "public"."projects"."is_insurance_claim"
  IS 'True when the project is driven by an insurance claim (hail, wind, storm damage).';
COMMENT ON COLUMN "public"."projects"."claim_number"
  IS 'Insurance claim reference number.';
COMMENT ON COLUMN "public"."projects"."insurance_company"
  IS 'Name of the insurance carrier handling the claim.';
COMMENT ON COLUMN "public"."projects"."adjuster_name"
  IS 'Name of the insurance adjuster assigned to this claim.';
COMMENT ON COLUMN "public"."projects"."adjuster_phone"
  IS 'Phone number for the insurance adjuster.';
COMMENT ON COLUMN "public"."projects"."date_of_loss"
  IS 'Date the damage event (storm, hail, etc.) occurred.';

-- Permit tracking
ALTER TABLE "public"."projects"
  ADD COLUMN IF NOT EXISTS "permit_required"    boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS "permit_number"      text,
  ADD COLUMN IF NOT EXISTS "permit_issued_date" date;

COMMENT ON COLUMN "public"."projects"."permit_required"
  IS 'True when a permit is required for this project.';
COMMENT ON COLUMN "public"."projects"."permit_number"
  IS 'Permit number issued by the local authority.';
COMMENT ON COLUMN "public"."projects"."permit_issued_date"
  IS 'Date the permit was issued.';

-- -----------------------------------------------------------------
-- PHASE 14 — Financial & measurement fields + quote_request link
-- -----------------------------------------------------------------

ALTER TABLE "public"."projects"
  ADD COLUMN IF NOT EXISTS "estimated_value"   numeric(12,2),
  ADD COLUMN IF NOT EXISTS "contract_amount"   numeric(12,2),
  ADD COLUMN IF NOT EXISTS "sq_ft_measurement" text;

COMMENT ON COLUMN "public"."projects"."estimated_value"
  IS 'Estimated project value before a contract is signed.';
COMMENT ON COLUMN "public"."projects"."contract_amount"
  IS 'Agreed contract amount once the customer has approved the job.';
COMMENT ON COLUMN "public"."projects"."sq_ft_measurement"
  IS 'Roof square footage measurement used for estimating.';

-- Link project back to originating web quote request (closes web-form → project loop)
ALTER TABLE "public"."projects"
  ADD COLUMN IF NOT EXISTS "quote_request_id" bigint
  REFERENCES "public"."quote_request"("id") ON DELETE SET NULL;

COMMENT ON COLUMN "public"."projects"."quote_request_id"
  IS 'FK to quote_request. Traces this project back to the original web form submission.';

-- -----------------------------------------------------------------
-- PHASE 15 — Defensive constraints
-- -----------------------------------------------------------------

-- UNIQUE on project_status.name (prevents duplicate status rows)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE  conname  = 'project_status_name_key'
      AND  conrelid = 'public.project_status'::regclass
  ) THEN
    ALTER TABLE public.project_status ADD CONSTRAINT project_status_name_key UNIQUE (name);
  END IF;
END;
$$;

-- UNIQUE on project_source.name
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE  conname  = 'project_source_name_key'
      AND  conrelid = 'public.project_source'::regclass
  ) THEN
    ALTER TABLE public.project_source ADD CONSTRAINT project_source_name_key UNIQUE (name);
  END IF;
END;
$$;

-- CHECK: end_date must not precede start_date
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE  conname  = 'projects_dates_check'
      AND  conrelid = 'public.projects'::regclass
  ) THEN
    ALTER TABLE public.projects
      ADD CONSTRAINT projects_dates_check
      CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date);
  END IF;
END;
$$;

-- NOT NULL on project_number (safe after IDENTITY + back-fill in Phase 4)
DO $$
DECLARE
  v_is_nullable text;
BEGIN
  SELECT is_nullable INTO v_is_nullable
  FROM   information_schema.columns
  WHERE  table_schema = 'public'
    AND  table_name   = 'projects'
    AND  column_name  = 'project_number';

  IF v_is_nullable = 'YES' THEN
    ALTER TABLE public.projects ALTER COLUMN project_number SET NOT NULL;
  END IF;
END;
$$;

-- -----------------------------------------------------------------
-- PHASE 16 — Indexes for new columns
-- -----------------------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_projects_project_type_id"
  ON "public"."projects" ("project_type_id");

CREATE INDEX IF NOT EXISTS "idx_projects_is_insurance_claim"
  ON "public"."projects" ("is_insurance_claim")
  WHERE "is_insurance_claim" = true;

CREATE INDEX IF NOT EXISTS "idx_projects_quote_request_id"
  ON "public"."projects" ("quote_request_id")
  WHERE "quote_request_id" IS NOT NULL;

CREATE INDEX IF NOT EXISTS "idx_projects_city"
  ON "public"."projects" ("city");

CREATE INDEX IF NOT EXISTS "idx_projects_state"
  ON "public"."projects" ("state");

COMMIT;

ROLLBACK;
